export * from './forge-client';
export * from './github-client';
export * from './gitlab-client';

export * from './review-service';
export * from './diff-service';
export * from './discussion-service';

export class UserError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'UserError';
  }
}

export class ApiError extends Error {
  constructor(
    message: string,
    public readonly statusCode: number,
    public readonly body?: unknown
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

export class StaleReviewError extends Error {
  constructor(
    message: string,
    public readonly cachedSha: string,
    public readonly currentSha: string
  ) {
    super(message);
    this.name = 'StaleReviewError';
  }
}

export const EXIT_CODES = {
  SUCCESS: 0,
  USER_ERROR: 1,
  API_ERROR: 2,
  STALE_REVIEW: 3,
} as const;

import { z } from 'zod';

// DiffVersion - SHAs needed for diff positioning
// GitHub: only headSha needed
// GitLab: all three SHAs needed
export const DiffVersionSchema = z.object({
  headSha: z.string(),
  baseSha: z.string().optional(),  // GitLab-only
  startSha: z.string().optional(),  // GitLab-only
});
export type DiffVersion = z.infer<typeof DiffVersionSchema>;

// PR/MR schema
export const PRSchema = z.object({
  id: z.number(),
  iid: z.number(),
  projectId: z.string(),
  title: z.string(),
  state: z.enum(['opened', 'closed', 'merged', 'locked']),
  sourceBranch: z.string(),
  targetBranch: z.string(),
  author: z.object({
    id: z.number(),
    username: z.string(),
    name: z.string(),
    avatarUrl: z.string().optional(),
  }),
  webUrl: z.string(),
  diffVersions: DiffVersionSchema.optional(),
});
export type PR = z.infer<typeof PRSchema>;

// ReviewComment - a draft comment (used by GitHub for local staging)
export const ReviewCommentSchema = z.object({
  id: z.string().optional(),  // client-generated ID for tracking
  file: z.string(),
  line: z.number().int().positive(),
  lineEnd: z.number().int().positive().optional(),
  side: z.enum(['new', 'old']).default('new'),
  body: z.string().min(1),
});
export type ReviewComment = z.infer<typeof ReviewCommentSchema>;

// DraftNote - a server-side GitLab draft note
export const DraftNoteSchema = z.object({
  id: z.number(),
  position: z.object({
    base_sha: z.string(),
    head_sha: z.string(),
    start_sha: z.string(),
    old_path: z.string(),
    new_path: z.string(),
    position_type: z.enum(['text', 'image']),
    new_line: z.number().optional(),
    old_line: z.number().optional(),
    line_range: z.object({
      start: z.object({
        type: z.enum(['new', 'old']),
        old_line: z.number().optional(),
        new_line: z.number().optional(),
      }),
      end: z.object({
        type: z.enum(['new', 'old']),
        old_line: z.number().optional(),
        new_line: z.number().optional(),
      }),
    }).optional(),
  }).optional(),
  note: z.string(),
  author: z.object({
    id: z.number(),
    username: z.string(),
    name: z.string(),
  }),
  created_at: z.string(),
});
export type DraftNote = z.infer<typeof DraftNoteSchema>;

// Discussion - an existing discussion thread
export const DiscussionSchema = z.object({
  id: z.string(),
  individual_note: z.boolean(),
  notes: z.array(z.object({
    id: z.number(),
    type: z.enum(['DiscussionNote', 'DiffNote', 'Note']).optional(),
    body: z.string(),
    author: z.object({
      id: z.number(),
      username: z.string(),
      name: z.string(),
    }),
    created_at: z.string(),
    resolvable: z.boolean().optional(),
    resolved: z.boolean().optional(),
    position: z.object({
      old_path: z.string().optional(),
      new_path: z.string().optional(),
      old_line: z.number().optional(),
      new_line: z.number().optional(),
    }).optional(),
  })),
});
export type Discussion = z.infer<typeof DiscussionSchema>;

// DiffHunk - a single hunk in a file diff
export const DiffHunkSchema = z.object({
  old_start: z.number(),
  old_lines: z.number(),
  new_start: z.number(),
  new_lines: z.number(),
  content: z.string(),
});
export type DiffHunk = z.infer<typeof DiffHunkSchema>;

// FileDiff - diff for a single file
export const FileDiffSchema = z.object({
  old_path: z.string(),
  new_path: z.string(),
  diff: z.string(),
  new_file: z.boolean(),
  deleted_file: z.boolean(),
  renamed_file: z.boolean(),
  hunks: z.array(DiffHunkSchema).optional(),
});
export type FileDiff = z.infer<typeof FileDiffSchema>;

// ReviewSession - local session state
// GitHub: uses comments array (local staging)
// GitLab: uses draftNoteIds (server-side drafts)
export const ReviewSessionSchema = z.object({
  projectId: z.string(),
  mrIid: z.number(),
  startedAt: z.string(),
  versions: DiffVersionSchema,
  // GitHub: local comments stored in session
  comments: z.array(ReviewCommentSchema).optional(),
  // GitLab: server-side draft note IDs
  draftNoteIds: z.array(z.number()).optional(),
});
export type ReviewSession = z.infer<typeof ReviewSessionSchema>;

// Config schema
export const ConfigSchema = z.object({
  forge: z.enum(['gitlab', 'github']).default('github'),
  token: z.string(),
  baseUrl: z.string().optional(),
  project: z.string().optional(),
});
export type Config = z.infer<typeof ConfigSchema>;

import type { DiffVersion, ReviewSession, ReviewComment, FileDiff, DiffHunk } from './schemas';

/**
 * Check if the review session is stale by comparing cached SHAs with current
 * GitHub: only compares headSha
 * GitLab: compares all three SHAs
 */
export function isStale(session: ReviewSession, currentVersions: DiffVersion): boolean {
  // Always compare headSha
  if (session.versions.headSha !== currentVersions.headSha) {
    return true;
  }

  // GitLab: also compare baseSha and startSha if present
  if (session.versions.baseSha && currentVersions.baseSha &&
      session.versions.baseSha !== currentVersions.baseSha) {
    return true;
  }

  if (session.versions.startSha && currentVersions.startSha &&
      session.versions.startSha !== currentVersions.startSha) {
    return true;
  }

  return false;
}

/**
 * Parse unified diff content into hunks with line numbers
 */
export function parseDiffHunks(diffContent: string): DiffHunk[] {
  const hunks: DiffHunk[] = [];
  const hunkRegex = /^@@ -(\d+),(\d+) \+(\d+),(\d+) @@/gm;
  let match;

  while ((match = hunkRegex.exec(diffContent)) !== null) {
    hunks.push({
      old_start: parseInt(match[1], 10),
      old_lines: parseInt(match[2], 10),
      new_start: parseInt(match[3], 10),
      new_lines: parseInt(match[4], 10),
      content: extractHunkContent(diffContent, match.index),
    });
  }

  return hunks;
}

function extractHunkContent(diff: string, startIndex: number): string {
  const lines = diff.slice(startIndex).split('\n');
  const hunkLines: string[] = [];

  for (const line of lines) {
    if (line.startsWith('@@') && hunkLines.length > 0) {
      break;
    }
    hunkLines.push(line);
  }

  return hunkLines.join('\n');
}

/**
 * Build a line number map for a file diff
 * Returns a map of line number -> { oldLine, newLine, type }
 */
export function buildLineMap(fileDiff: FileDiff): Map<number, { oldLine?: number; newLine?: number; type: 'context' | 'addition' | 'deletion' }> {
  const lineMap = new Map();
  const hunks = fileDiff.hunks || parseDiffHunks(fileDiff.diff);

  let displayLine = 1;

  for (const hunk of hunks) {
    let oldLine = hunk.old_start;
    let newLine = hunk.new_start;

    const lines = hunk.content.split('\n').slice(1); // Skip the @@ line

    for (const line of lines) {
      if (line.startsWith('+')) {
        lineMap.set(displayLine, { newLine, type: 'addition' });
        newLine++;
        displayLine++;
      } else if (line.startsWith('-')) {
        lineMap.set(displayLine, { oldLine, type: 'deletion' });
        oldLine++;
        displayLine++;
      } else if (line.startsWith(' ')) {
        lineMap.set(displayLine, { oldLine, newLine, type: 'context' });
        oldLine++;
        newLine++;
        displayLine++;
      }
    }
  }

  return lineMap;
}

/**
 * Normalize project ID to group/repo format
 */
export function normalizeProjectId(id: string | number): string {
  if (typeof id === 'number') {
    // Numeric ID - will need to be resolved via API
    return String(id);
  }
  return id;
}

/**
 * Create a GitLab position object for a comment
 */
export function createGitLabPosition(
  comment: ReviewComment,
  versions: DiffVersion,
  filePath: string
): {
  base_sha: string;
  head_sha: string;
  start_sha: string;
  position_type: 'text';
  new_path: string;
  old_path: string;
  new_line?: number;
  old_line?: number;
} {
  const position: ReturnType<typeof createGitLabPosition> = {
    base_sha: versions.baseSha,
    head_sha: versions.headSha,
    start_sha: versions.startSha,
    position_type: 'text',
    new_path: filePath,
    old_path: filePath,
  };

  if (comment.side === 'new') {
    position.new_line = comment.line;
  } else {
    position.old_line = comment.line;
  }

  return position;
}

/**
 * Create a GitLab line range for multi-line comments
 */
export function createGitLabLineRange(
  startLine: number,
  endLine: number,
  side: 'new' | 'old'
): {
  start: { type: 'new' | 'old'; new_line?: number; old_line?: number };
  end: { type: 'new' | 'old'; new_line?: number; old_line?: number };
} {
  return {
    start: {
      type: side,
      [side === 'new' ? 'new_line' : 'old_line']: startLine,
    },
    end: {
      type: side,
      [side === 'new' ? 'new_line' : 'old_line']: endLine,
    },
  };
}

import { $ } from 'bun';
import { ConfigSchema, type Config } from './entity/schemas';
import { UserError } from './errors';

const GITLAB_DEFAULT_URL = 'https://gitlab.com';
const GITHUB_DEFAULT_URL = 'https://api.github.com';

/**
 * Load configuration from environment and optional config file
 */
export async function loadConfig(options?: Partial<Config>): Promise<Config> {
  const forge = options?.forge ?? (process.env.GITLAB_TOKEN ? 'gitlab' : 'github');

  const token = options?.token ?? 
    (forge === 'gitlab' ? process.env.GITLAB_TOKEN : process.env.GITHUB_TOKEN);

  if (!token) {
    throw new UserError(
      `No ${forge === 'gitlab' ? 'GITLAB_TOKEN' : 'GITHUB_TOKEN'} environment variable found. ` +
      'Set it or use --token flag.'
    );
  }

  const baseUrl = options?.baseUrl ?? 
    (forge === 'gitlab' 
      ? process.env.GITLAB_URL ?? GITLAB_DEFAULT_URL
      : GITHUB_DEFAULT_URL);

  const project = options?.project ?? await detectProject(forge);

  return ConfigSchema.parse({
    forge,
    token,
    baseUrl,
    project,
  });
}

/**
 * Detect project from git remote
 */
export async function detectProject(forge: 'gitlab' | 'github'): Promise<string | undefined> {
  try {
    const result = await $`git remote get-url origin`.quiet();
    const remoteUrl = result.text().trim();

    return parseProjectFromRemote(remoteUrl, forge);
  } catch {
    return undefined;
  }
}

/**
 * Parse project ID from git remote URL
 */
function parseProjectFromRemote(url: string, forge: 'gitlab' | 'github'): string | undefined {
  // SSH format: git@gitlab.com:group/repo.git
  // HTTPS format: https://gitlab.com/group/repo.git

  const patterns = forge === 'gitlab'
    ? [/gitlab\.com[/:]([^/]+\/[^/]+?)(?:\.git)?$/, /gitlab\.[^/]+[/:]([^/]+\/[^/]+?)(?:\.git)?$/]
    : [/github\.com[/:]([^/]+\/[^/]+?)(?:\.git)?$/, /github\.[^/]+[/:]([^/]+\/[^/]+?)(?:\.git)?$/];

  for (const pattern of patterns) {
    const match = url.match(pattern);
    if (match) {
      return match[1];
    }
  }

  return undefined;
}

import type { PR, DiffVersion, DraftNote, Discussion, FileDiff, ReviewComment } from '../entity/schemas';

/**
 * ForgeClient interface - all forge-specific logic lives here
 * Zero leakage into CLI layer
 * 
 * Design: The interface abstracts the two different approaches:
 * - GitHub: local staging (comments stored in session, submitted via POST /reviews)
 * - GitLab: server-side drafts (draft_notes API)
 */
export interface ForgeClient {
  // Forge identification
  readonly forge: 'github' | 'gitlab';

  // Project operations
  getProjectId(projectPath: string): Promise<string>;

  // MR/PR operations
  listPRs(opts: { state?: string; limit?: number }): Promise<PR[]>;
  getPR(projectId: string, mrIid: number): Promise<PR>;
  createPR(opts: { title: string; sourceBranch: string; targetBranch: string; description?: string; draft?: boolean }): Promise<PR>;
  approvePR(projectId: string, mrIid: number): Promise<void>;
  unapprovePR(projectId: string, mrIid: number): Promise<void>;
  mergePR(projectId: string, mrIid: number): Promise<void>;

  // Diff operations
  getDiff(projectId: string, mrIid: number): Promise<FileDiff[]>;
  getVersions(projectId: string, mrIid: number): Promise<DiffVersion>;

  // Review operations (forge-agnostic)
  // GitHub: stores in session, GitLab: creates server-side draft
  addComment(projectId: string, mrIid: number, opts: CommentOptions): Promise<CommentResult>;
  // GitHub: reads from session, GitLab: lists server-side drafts
  listComments(projectId: string, mrIid: number): Promise<CommentResult[]>;
  // GitHub: POST /reviews with comments, GitLab: publish draft notes
  submitReview(projectId: string, mrIid: number, opts?: { summary?: string }): Promise<void>;
  // GitHub: clears session, GitLab: deletes server-side drafts
  discardReview(projectId: string, mrIid: number): Promise<void>;

  // Discussion operations
  listDiscussions(projectId: string, mrIid: number): Promise<Discussion[]>;
  resolveDiscussion(projectId: string, mrIid: number, discussionId: string): Promise<void>;
  unresolveDiscussion(projectId: string, mrIid: number, discussionId: string): Promise<void>;
  createNote(projectId: string, mrIid: number, opts: { body: string; position?: unknown }): Promise<void>;
}

/**
 * Comment options - forge-agnostic comment creation
 */
export interface CommentOptions {
  body: string;
  file: string;
  line: number;
  lineEnd?: number;
  side?: 'new' | 'old';
}

/**
 * Comment result - represents a staged comment
 * GitHub: has client-generated id, GitLab: has server-assigned id
 */
export interface CommentResult {
  id: string | number;
  body: string;
  file: string;
  line: number;
  lineEnd?: number;
  side: 'new' | 'old';
}

/**
 * GitLab-specific draft note options (for internal use)
 */
export interface DraftNoteOptions {
  body: string;
  position?: {
    base_sha: string;
    head_sha: string;
    start_sha: string;
    position_type: 'text';
    new_path: string;
    old_path: string;
    new_line?: number;
    old_line?: number;
    line_range?: {
      start: { type: 'new' | 'old'; new_line?: number; old_line?: number };
      end: { type: 'new' | 'old'; new_line?: number; old_line?: number };
    };
  };
}

import type { ForgeClient, CommentOptions, CommentResult } from './forge-client';
import type { PR, DiffVersion, Discussion, FileDiff, ReviewComment } from '../entity/schemas';
import { ApiError, UserError } from '../errors';
import { SessionStore } from '../session/session-store';

interface GitHubClientOptions {
  baseUrl: string;
  token: string;
}

/**
 * GitHub client implementation
 * 
 * Key differences from GitLab:
 * - No server-side drafts - comments stored in local session
 * - submitReview: POST /repos/:owner/:repo/pulls/:number/reviews with comments array
 * - Only one headSha needed (not three SHAs like GitLab)
 */
export class GitHubClient implements ForgeClient {
  readonly forge = 'github' as const;
  private baseUrl: string;
  private token: string;

  constructor(opts: GitHubClientOptions) {
    this.baseUrl = opts.baseUrl.replace(/\/$/, '');
    this.token = opts.token;
  }

  private async request<T>(
    method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH',
    path: string,
    body?: unknown
  ): Promise<T> {
    const url = `${this.baseUrl}${path}`;

    const response = await fetch(url, {
      method,
      headers: {
        'Authorization': `Bearer ${this.token}`,
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
        'Content-Type': 'application/json',
      },
      body: body ? JSON.stringify(body) : undefined,
    });

    if (!response.ok) {
      const errorBody = await response.text();
      throw new ApiError(
        `GitHub API error: ${response.status} ${response.statusText}`,
        response.status,
        errorBody
      );
    }

    if (response.status === 204) {
      return undefined as T;
    }

    return response.json();
  }

  private parseProjectId(projectId: string): { owner: string; repo: string } {
    const [owner, repo] = projectId.split('/');
    if (!owner || !repo) {
      throw new UserError(`Invalid project ID format: ${projectId}. Expected 'owner/repo'.`);
    }
    return { owner, repo };
  }

  // Project operations
  async getProjectId(projectPath: string): Promise<string> {
    // GitHub uses owner/repo format directly
    return projectPath;
  }

  // PR operations
  async listPRs(opts: { state?: string; limit?: number } = {}): Promise<PR[]> {
    // TODO: Implement via GET /repos/:owner/:repo/pulls
    throw new Error('Not implemented');
  }

  async getPR(projectId: string, prNumber: number): Promise<PR> {
    const { owner, repo } = this.parseProjectId(projectId);
    const pr = await this.request<any>(
      'GET',
      `/repos/${owner}/${repo}/pulls/${prNumber}`
    );

    return {
      id: pr.id,
      iid: pr.number,
      projectId: `${owner}/${repo}`,
      title: pr.title,
      state: pr.state === 'open' ? 'opened' : pr.state,
      sourceBranch: pr.head.ref,
      targetBranch: pr.base.ref,
      author: {
        id: pr.user.id,
        username: pr.user.login,
        name: pr.user.login,
        avatarUrl: pr.user.avatar_url,
      },
      webUrl: pr.html_url,
      diffVersions: {
        headSha: pr.head.sha,
      },
    };
  }

  async createPR(opts: { title: string; sourceBranch: string; targetBranch: string; description?: string; draft?: boolean }): Promise<PR> {
    // TODO: Implement via POST /repos/:owner/:repo/pulls
    throw new Error('Not implemented');
  }

  async approvePR(projectId: string, prNumber: number): Promise<void> {
    const { owner, repo } = this.parseProjectId(projectId);
    await this.request(
      'POST',
      `/repos/${owner}/${repo}/pulls/${prNumber}/reviews`,
      { event: 'APPROVE' }
    );
  }

  async unapprovePR(projectId: string, prNumber: number): Promise<void> {
    // GitHub doesn't have a direct unapprove - need to dismiss the review
    // TODO: Implement via PUT /repos/:owner/:repo/pulls/:number/reviews/:review_id/dismissals
    throw new Error('Not implemented');
  }

  async mergePR(projectId: string, prNumber: number): Promise<void> {
    const { owner, repo } = this.parseProjectId(projectId);
    await this.request(
      'PUT',
      `/repos/${owner}/${repo}/pulls/${prNumber}/merge`
    );
  }

  // Diff operations
  async getDiff(projectId: string, prNumber: number): Promise<FileDiff[]> {
    const { owner, repo } = this.parseProjectId(projectId);
    // TODO: Implement via GET /repos/:owner/:repo/pulls/:number/files
    throw new Error('Not implemented');
  }

  async getVersions(projectId: string, prNumber: number): Promise<DiffVersion> {
    const pr = await this.getPR(projectId, prNumber);
    return {
      headSha: pr.diffVersions?.headSha ?? '',
    };
  }

  // Review operations (GitHub: local staging)
  async addComment(projectId: string, prNumber: number, opts: CommentOptions): Promise<CommentResult> {
    const session = await SessionStore.read(projectId, prNumber);
    const comment: ReviewComment = {
      id: crypto.randomUUID(),
      file: opts.file,
      line: opts.line,
      lineEnd: opts.lineEnd,
      side: opts.side ?? 'new',
      body: opts.body,
    };

    const comments = session?.comments ?? [];
    comments.push(comment);

    await SessionStore.write(projectId, prNumber, {
      projectId,
      mrIid: prNumber,
      startedAt: session?.startedAt ?? new Date().toISOString(),
      versions: session?.versions ?? { headSha: '' },
      comments,
    });

    return {
      id: comment.id!,
      body: comment.body,
      file: comment.file,
      line: comment.line,
      lineEnd: comment.lineEnd,
      side: comment.side,
    };
  }

  async listComments(projectId: string, prNumber: number): Promise<CommentResult[]> {
    const session = await SessionStore.read(projectId, prNumber);
    return (session?.comments ?? []).map(c => ({
      id: c.id!,
      body: c.body,
      file: c.file,
      line: c.line,
      lineEnd: c.lineEnd,
      side: c.side,
    }));
  }

  async submitReview(projectId: string, prNumber: number, opts?: { summary?: string }): Promise<void> {
    const { owner, repo } = this.parseProjectId(projectId);
    const session = await SessionStore.read(projectId, prNumber);

    if (!session?.comments?.length) {
      throw new UserError('No comments to submit');
    }

    // Build GitHub review comments format
    const comments = session.comments.map(c => ({
      path: c.file,
      line: c.line,
      side: c.side === 'old' ? 'LEFT' : 'RIGHT',
      body: c.body,
    }));

    await this.request(
      'POST',
      `/repos/${owner}/${repo}/pulls/${prNumber}/reviews`,
      {
        event: 'COMMENT',
        body: opts?.summary ?? '',
        comments,
      }
    );

    // Clear session after successful submit
    await SessionStore.delete(projectId, prNumber);
  }

  async discardReview(projectId: string, prNumber: number): Promise<void> {
    await SessionStore.delete(projectId, prNumber);
  }

  // Discussion operations
  async listDiscussions(projectId: string, prNumber: number): Promise<Discussion[]> {
    // GitHub uses review comments, not discussions
    // TODO: Implement via GET /repos/:owner/:repo/pulls/:number/comments
    throw new Error('Not implemented');
  }

  async resolveDiscussion(projectId: string, prNumber: number, discussionId: string): Promise<void> {
    // GitHub doesn't have discussion resolution like GitLab
    throw new Error('Not implemented');
  }

  async unresolveDiscussion(projectId: string, prNumber: number, discussionId: string): Promise<void> {
    // GitHub doesn't have discussion resolution like GitLab
    throw new Error('Not implemented');
  }

  async createNote(projectId: string, prNumber: number, opts: { body: string; position?: unknown }): Promise<void> {
    const { owner, repo } = this.parseProjectId(projectId);
    await this.request(
      'POST',
      `/repos/${owner}/${repo}/issues/${prNumber}/comments`,
      { body: opts.body }
    );
  }
}

import { test, expect, describe, mock, beforeEach } from 'bun:test';
import { GitHubClient } from './github-client';
import { ApiError } from '../errors';

describe('GitHubClient', () => {
  const mockFetch = mock();
  const client = new GitHubClient({
    baseUrl: 'https://api.github.com',
    token: 'test-token',
  });

  beforeEach(() => {
    mockFetch.mockClear();
    global.fetch = mockFetch;
  });

  describe('getVersions', () => {
    test('returns DiffVersion with headSha from PR', async () => {
      mockFetch.mockResolvedValueOnce({
        ok: true,
        json: () => ({
          id: 1,
          number: 42,
          title: 'Test PR',
          state: 'open',
          head: { ref: 'feature', sha: 'abc123' },
          base: { ref: 'main', sha: 'def456' },
          user: { id: 1, login: 'testuser', avatar_url: 'https://example.com/avatar.png' },
          html_url: 'https://github.com/owner/repo/pull/42',
        }),
      });

      const versions = await client.getVersions('owner/repo', 42);

