interface GitLabClientOptions {
  baseUrl: string;
  token: string;
}

/**
 * GitLab client implementation
 * 
 * Key differences from GitHub:
 * - Server-side drafts via draft_notes API
 * - Three SHAs needed (head, base, start) for position
 * - publishDraftNotes: POST /projects/:id/merge_requests/:iid/draft_notes/bulk_publish
 */
export class GitLabClient implements ForgeClient {
  readonly forge = 'gitlab' as const;
  private baseUrl: string;
  private token: string;

  constructor(opts: GitLabClientOptions) {
    this.baseUrl = opts.baseUrl.replace(/\/$/, '');
    this.token = opts.token;
  }

  private async request<T>(
    method: 'GET' | 'POST' | 'PUT' | 'DELETE',
    path: string,
    body?: unknown
  ): Promise<T> {
    const url = `${this.baseUrl}/api/v4${path}`;

    const response = await fetch(url, {
      method,
      headers: {
        'PRIVATE-TOKEN': this.token,
        'Content-Type': 'application/json',
      },
      body: body ? JSON.stringify(body) : undefined,
    });

    if (!response.ok) {
      const errorBody = await response.text();
      throw new ApiError(
        `GitLab API error: ${response.status} ${response.statusText}`,
        response.status,
        errorBody
      );
    }

    return response.json();
  }

  private encodeProjectId(projectId: string): string {
    return encodeURIComponent(projectId);
  }

  // Project operations
  async getProjectId(projectPath: string): Promise<string> {
    if (projectPath.includes('/')) {
      return projectPath;
    }
    const project = await this.request<{ path_with_namespace: string }>(
      'GET',
      `/projects/${projectPath}`
    );
    return project.path_with_namespace;
  }

  // MR/PR operations
  async listPRs(opts: { state?: string; limit?: number } = {}): Promise<PR[]> {
