  // Diff operations
  async getDiff(projectId: string, mrIid: number): Promise<FileDiff[]> {
    // TODO: Implement
    throw new Error('Not implemented');
  }

  async getVersions(projectId: string, mrIid: number): Promise<DiffVersion> {
    const versions = await this.request<any[]>(
      'GET',
      `/projects/${this.encodeProjectId(projectId)}/merge_requests/${mrIid}/versions`
    );

    if (!versions.length) {
      throw new ApiError('No versions found for MR', 404);
    }

    const latest = versions[0];
    return {
      headSha: latest.head_commit_sha,
      baseSha: latest.base_commit_sha,
      startSha: latest.start_commit_sha,
    };
  }

  // Review operations (GitLab: server-side drafts)
  async addComment(projectId: string, mrIid: number, opts: CommentOptions): Promise<CommentResult> {
    const versions = await this.getVersions(projectId, mrIid);

    const draftNote = await this.createDraftNoteInternal(projectId, mrIid, {
      body: opts.body,
      position: {
        base_sha: versions.baseSha!,
        head_sha: versions.headSha,
        start_sha: versions.startSha!,
        position_type: 'text',
        new_path: opts.file,
        old_path: opts.file,
        new_line: opts.side === 'new' ? opts.line : undefined,
        old_line: opts.side === 'old' ? opts.line : undefined,
      },
    });

    return {
      id: draftNote.id,
      body: draftNote.note,
      file: opts.file,
      line: opts.line,
      side: opts.side ?? 'new',
    };
  }

  async listComments(projectId: string, mrIid: number): Promise<CommentResult[]> {
    const drafts = await this.listDraftNotesInternal(projectId, mrIid);
    return drafts.map(d => ({
      id: d.id,
      body: d.note,
      file: d.position?.new_path ?? d.position?.old_path ?? '',
      line: d.position?.new_line ?? d.position?.old_line ?? 0,
      side: d.position?.new_line ? 'new' : 'old',
    }));
  }

  async submitReview(projectId: string, mrIid: number, opts?: { summary?: string }): Promise<void> {
    await this.request(
      'POST',
      `/projects/${this.encodeProjectId(projectId)}/merge_requests/${mrIid}/draft_notes/bulk_publish`,
      { summary: opts?.summary }
    );
  }

  async discardReview(projectId: string, mrIid: number): Promise<void> {
    const drafts = await this.listDraftNotesInternal(projectId, mrIid);
    for (const draft of drafts) {
      await this.deleteDraftNoteInternal(projectId, mrIid, draft.id);
    }
  }

  // Internal draft note operations
  private async createDraftNoteInternal(projectId: string, mrIid: number, opts: DraftNoteOptions): Promise<DraftNote> {
    return this.request<DraftNote>(
      'POST',
      `/projects/${this.encodeProjectId(projectId)}/merge_requests/${mrIid}/draft_notes`,
      opts
    );
  }

  private async listDraftNotesInternal(projectId: string, mrIid: number): Promise<DraftNote[]> {
    return this.request<DraftNote[]>(
      'GET',
      `/projects/${this.encodeProjectId(projectId)}/merge_requests/${mrIid}/draft_notes`
    );
  }

  private async deleteDraftNoteInternal(projectId: string, mrIid: number, draftNoteId: number): Promise<void> {
    await this.request(
      'DELETE',
      `/projects/${this.encodeProjectId(projectId)}/merge_requests/${mrIid}/draft_notes/${draftNoteId}`
    );
  }

