import type { ForgeClient, CommentOptions } from '../client/forge-client';
import type { ReviewSession, ReviewComment, DiffVersion, CommentResult } from '../entity/schemas';
import { SessionStore } from '../session/session-store';
import { isStale } from '../entity/transforms';
import { StaleReviewError, UserError } from '../errors';

export interface ReviewServiceOptions {
  client: ForgeClient;
  projectId: string;
  mrIid: number;
}

export const ReviewService = {
  /**
   * Start a new review session
   */
  async startReview(opts: ReviewServiceOptions): Promise<ReviewSession> {
    const existing = await SessionStore.read(opts.projectId, opts.mrIid);
    if (existing) {
      return existing;
    }

    const versions = await opts.client.getVersions(opts.projectId, opts.mrIid);

    const session: ReviewSession = {
      projectId: opts.projectId,
      mrIid: opts.mrIid,
      startedAt: new Date().toISOString(),
      versions,
      // GitHub: comments array, GitLab: draftNoteIds
      ...(opts.client.forge === 'github' ? { comments: [] } : { draftNoteIds: [] }),
    };

    await SessionStore.write(opts.projectId, opts.mrIid, session);

    return session;
  },

  /**
   * Get current session status
   */
  async getStatus(opts: ReviewServiceOptions): Promise<{
    session: ReviewSession | null;
    isStale: boolean;
    currentVersions: DiffVersion | null;
    comments: CommentResult[];
  }> {
    const session = await SessionStore.read(opts.projectId, opts.mrIid);

    if (!session) {
      return {
        session: null,
        isStale: false,
        currentVersions: null,
        comments: [],
      };
    }

    const currentVersions = await opts.client.getVersions(opts.projectId, opts.mrIid);
    const stale = isStale(session, currentVersions);

    // Use forge-agnostic listComments
    const comments = await opts.client.listComments(opts.projectId, opts.mrIid);

    return {
      session,
      isStale: stale,
      currentVersions,
      comments,
    };
  },ons,
      draftNotes,
    };
  },

  /**
   * Add a comment to the review
   */
  async addComment(
    opts: ReviewServiceOptions,
    comment: ReviewComment
  ): Promise<DraftNote> {
    const session = await SessionStore.read(opts.projectId, opts.mrIid);

    if (!session) {
      throw new UserError(
        'No active review session. Run `gfreview review start <id>` first.'
      );
    }

    // Check staleness
    const currentVersions = await opts.client.getVersions(opts.projectId, opts.mrIid);
    if (isStale(session, currentVersions)) {
      throw new StaleReviewError(
        'Review is stale. Run `gfreview review refresh <id>` to update.',
        session.versions.headSha,
        currentVersions.headSha
      );
    }

    // Create draft note
    const position: DraftNoteOptions['position'] = createGitLabPosition(
      comment,
      session.versions,
      comment.file
    );

    // Handle multi-line comments
    if (comment.lineEnd) {
      position.line_range = createGitLabLineRange(
        comment.line,
        comment.lineEnd,
        comment.side
      );
    }

    const draftNote = await opts.client.createDraftNote(opts.projectId, opts.mrIid, {
      body: comment.body,
      position,
    });

    // Update session with new draft note ID
    session.draftNoteIds.push(draftNote.id);
    await SessionStore.write(opts.projectId, opts.mrIid, session);

    return draftNote;
  },

  /**
   * Submit the review
   */
  async submitReview(
    opts: ReviewServiceOptions,
    summary?: string
  ): Promise<void> {
    const session = await SessionStore.read(opts.projectId, opts.mrIid);

    if (!session) {
      throw new UserError(
        'No active review session. Run `gfreview review start <id>` first.'
      );
    }

    // Check staleness
    const currentVersions = await opts.client.getVersions(opts.projectId, opts.mrIid);
    if (isStale(session, currentVersions)) {
      throw new StaleReviewError(
        'Review is stale. Run `gfreview review refresh <id>` to update.',
        session.versions.headSha,
        currentVersions.headSha
      );
    }

    // Publish all draft notes
    await opts.client.publishDraftNotes(opts.projectId, opts.mrIid, {
      summary,
    });

    // Clean up session
    await SessionStore.delete(opts.projectId, opts.mrIid);
  },

  /**
   * Discard the review
   */
  async discardReview(opts: ReviewServiceOptions): Promise<void> {
    const session = await SessionStore.read(opts.projectId, opts.mrIid);

    if (!session) {
      throw new UserError('No active review session to discard.');
    }

    // Delete all draft notes
    for (const noteId of session.draftNoteIds) {
      try {
        await opts.client.deleteDraftNote(opts.projectId, opts.mrIid, noteId);
      } catch {
        // Ignore errors - draft may have been deleted
      }
    }

    // Delete session
    await SessionStore.delete(opts.projectId, opts.mrIid);
  },

  /**
   * Refresh the review against the latest diff
   */
  async refreshReview(opts: ReviewServiceOptions): Promise<{
    updated: number;
    conflicts: Array<{ note: DraftNote; reason: string }>;
  }> {
    const session = await SessionStore.read(opts.projectId, opts.mrIid);

    if (!session) {
      throw new UserError(
        'No active review session. Run `gfreview review start <id>` first.'
      );
    }

    const newVersions = await opts.client.getVersions(opts.projectId, opts.mrIid);
    const draftNotes = await opts.client.listDraftNotes(opts.projectId, opts.mrIid);

    const conflicts: Array<{ note: DraftNote; reason: string }> = [];
    let updated = 0;

    // Get the new diff to check line existence
    const diffs = await opts.client.getDiff(opts.projectId, opts.mrIid);
    const fileMap = new Map(diffs.map(d => [d.new_path, d]));

    for (const note of draftNotes) {
      if (!note.position) continue;

      const filePath = note.position.new_path;
      const fileDiff = fileMap.get(filePath);

      if (!fileDiff) {
        conflicts.push({
          note,
          reason: `File ${filePath} no longer exists in diff`,
        });
        continue;
      }

      // Check if line still exists
      const line = note.position.new_line ?? note.position.old_line;
      if (line) {
        // For now, we assume the line exists if the file exists
        // A more thorough check would parse the diff and verify line numbers

        // Update the draft note with new SHAs
        await opts.client.deleteDraftNote(opts.projectId, opts.mrIid, note.id);

        const newPosition = {
          ...note.position,
          base_sha: newVersions.baseSha,
          head_sha: newVersions.headSha,
          start_sha: newVersions.startSha,
        };

        await opts.client.createDraftNote(opts.projectId, opts.mrIid, {
          body: note.note,
          position: newPosition,
        });

        updated++;
      }
    }

    // Update session with new versions
    session.versions = newVersions;
    await SessionStore.write(opts.projectId, opts.mrIid, session);

    return { updated, conflicts };
  },
};

import type { ForgeClient } from '../client/forge-client';
import type { FileDiff, DiffHunk } from '../entity/schemas';
import { parseDiffHunks, buildLineMap } from '../entity/transforms';

export interface DiffServiceOptions {
  client: ForgeClient;
  projectId: string;
  mrIid: number;
}

export interface FormattedDiff {
  path: string;
  oldPath: string;
  newPath: string;
  changeType: 'added' | 'deleted' | 'modified' | 'renamed';
  lines: DiffLine[];
}

export interface DiffLine {
  displayNumber: number;
  oldNumber?: number;
  newNumber?: number;
  content: string;
  type: 'context' | 'addition' | 'deletion';
}

export const DiffService = {
  /**
   * Get formatted diff with line numbers
   */
  async getDiff(opts: DiffServiceOptions): Promise<FormattedDiff[]> {
    const diffs = await opts.client.getDiff(opts.projectId, opts.mrIid);

    return diffs.map(d => this.formatFileDiff(d));
  },

  /**
   * Format a single file diff
   */
  formatFileDiff(fileDiff: FileDiff): FormattedDiff {
    const hunks = fileDiff.hunks || parseDiffHunks(fileDiff.diff);
    const lines: DiffLine[] = [];

    let displayNumber = 1;

    for (const hunk of hunks) {
      let oldLine = hunk.old_start;
      let newLine = hunk.new_start;

      const hunkLines = hunk.content.split('\n').slice(1); // Skip @@ line

      for (const line of hunkLines) {
        if (!line) continue;

        if (line.startsWith('+')) {
          lines.push({
            displayNumber: displayNumber++,
            newNumber: newLine++,
            content: line.slice(1),
            type: 'addition',
          });
        } else if (line.startsWith('-')) {
          lines.push({
            displayNumber: displayNumber++,
            oldNumber: oldLine++,
            content: line.slice(1),
            type: 'deletion',
          });
        } else if (line.startsWith(' ')) {
          lines.push({
            displayNumber: displayNumber++,
            oldNumber: oldLine++,
            newNumber: newLine++,
            content: line.slice(1),
            type: 'context',
          });
        }
      }
    }

    let changeType: FormattedDiff['changeType'] = 'modified';
    if (fileDiff.new_file) changeType = 'added';
    else if (fileDiff.deleted_file) changeType = 'deleted';
    else if (fileDiff.renamed_file) changeType = 'renamed';

    return {
      path: fileDiff.new_path,
      oldPath: fileDiff.old_path,
      newPath: fileDiff.new_path,
      changeType,
      lines,
    };
  },

  /**
   * Format diff for display
   */
  formatForDisplay(diff: FormattedDiff): string {
    const lines: string[] = [];

    // Header
    const changeTypeLabel = {
      added: 'new file',
      deleted: 'deleted',
      modified: 'modified',
      renamed: 'renamed',
    }[diff.changeType];

    lines.push(`\x1b[1;36m${diff.path}\x1b[0m (${changeTypeLabel})`);
    lines.push('─'.repeat(60));

    for (const line of diff.lines) {
      const lineNum = String(line.displayNumber).padStart(4);
      const oldNum = line.oldNumber ? String(line.oldNumber).padStart(4) : '    ';
      const newNum = line.newNumber ? String(line.newNumber).padStart(4) : '    ';

      let prefix = ' ';
      let color = '';

      if (line.type === 'addition') {
        prefix = '+';
        color = '\x1b[32m';
      } else if (line.type === 'deletion') {
        prefix = '-';
        color = '\x1b[31m';
      }

      const reset = color ? '\x1b[0m' : '';
      lines.push(`${lineNum} ${oldNum} ${newNum} ${color}${prefix}${line.content}${reset}`);
    }

    lines.push('');
    return lines.join('\n');
  },
};

import type { ForgeClient } from '../client/forge-client';
import type { Discussion } from '../entity/schemas';

export interface DiscussionServiceOptions {
  client: ForgeClient;
  projectId: string;
  mrIid: number;
}

export interface FormattedDiscussion {
  id: string;
  isResolved: boolean;
  isInline: boolean;
  file?: string;
  line?: number;
  notes: Array<{
    author: string;
    body: string;
    createdAt: string;
  isDraft?: boolean;
  }>;
}

export const DiscussionService = {
  /**
   * List all discussions
   */
  async list(opts: DiscussionServiceOptions): Promise<FormattedDiscussion[]> {
    const discussions = await opts.client.listDiscussions(opts.projectId, opts.mrIid);

    return discussions.map(d => this.formatDiscussion(d));
  },

  /**
   * Format a discussion for display
   */
  formatDiscussion(discussion: Discussion): FormattedDiscussion {
    const firstNote = discussion.notes[0];
    const isInline = firstNote?.position?.new_path !== undefined || 
                    firstNote?.position?.old_path !== undefined;

    return {
      id: discussion.id,
      isResolved: firstNote?.resolved ?? false,
      isInline,
      file: firstNote?.position?.new_path ?? firstNote?.position?.old_path,
      line: firstNote?.position?.new_line ?? firstNote?.position?.old_line,
      notes: discussion.notes.map(n => ({
        author: n.author.username,
        body: n.body,
        createdAt: n.created_at,
      })),
    };
  },

  /**
   * Format discussions for display
   */
  formatForDisplay(discussions: FormattedDiscussion[]): string {
    const lines: string[] = [];

    for (const d of discussions) {
      const statusIcon = d.isResolved ? '✓' : '○';
      const typeLabel = d.isInline ? 'inline' : 'general';

      lines.push(`\x1b[1m${statusIcon} Discussion ${d.id.slice(0, 8)}\x1b[0m (${typeLabel})`);

      if (d.isInline && d.file) {
        lines.push(`  File: ${d.file}${d.line ? `:${d.line}` : ''}`);
      }

      for (const note of d.notes) {
        const date = new Date(note.createdAt).toLocaleDateString();
        lines.push(`  \x1b[36m${note.author}\x1b[0m (${date}):`);
        lines.push(`    ${note.body.split('\n').join('\n    ')}`);
      }

      lines.push('');
    }

    return lines.join('\n');
  },

  /**
   * Resolve a discussion
   */
  async resolve(opts: DiscussionServiceOptions, discussionId: string): Promise<void> {
    await opts.client.resolveDiscussion(opts.projectId, opts.mrIid, discussionId);
  },

  /**
   * Unresolve a discussion
   */
  async unresolve(opts: DiscussionServiceOptions, discussionId: string): Promise<void> {
    await opts.client.unresolveDiscussion(opts.projectId, opts.mrIid, discussionId);
  },

  /**
   * Add a general note (not inline)
   */
  async addNote(opts: DiscussionServiceOptions, body: string): Promise<void> {
    await opts.client.createNote(opts.projectId, opts.mrIid, { body });
  },
};

