import { test, expect, describe } from 'bun:test';
import { DiffService } from './diff-service';
import type { FileDiff } from '../entity/schemas';

describe('DiffService', () => {
  describe('formatFileDiff', () => {
    test('parses simple diff with additions and deletions', () => {
      const fileDiff: FileDiff = {
        old_path: 'test.ts',
        new_path: 'test.ts',
        diff: '@@ -1,3 +1,4 @@\n old line 1\n-old line 2\n+new line 2\n+new line 3\n old line 3',
        new_file: false,
        deleted_file: false,
        renamed_file: false,
      };

      const result = DiffService.formatFileDiff(fileDiff);

      expect(result.path).toBe('test.ts');
      expect(result.changeType).toBe('modified');
      expect(result.lines).toHaveLength(4);

      // Check line types
      expect(result.lines[0].type).toBe('context');
      expect(result.lines[1].type).toBe('deletion');
      expect(result.lines[2].type).toBe('addition');
      expect(result.lines[3].type).toBe('addition');
    });

    test('marks new file as added', () => {
      const fileDiff: FileDiff = {
        old_path: '/dev/null',
        new_path: 'new-file.ts',
        diff: '@@ -0,0 +1,1 @@\n+new content',
        new_file: true,
        deleted_file: false,
        renamed_file: false,
      };

      const result = DiffService.formatFileDiff(fileDiff);

      expect(result.changeType).toBe('added');
    });

    test('assigns sequential display numbers', () => {
      const fileDiff: FileDiff = {
        old_path: 'test.ts',
        new_path: 'test.ts',
        diff: '@@ -1,2 +1,2 @@\n line 1\n line 2',
        new_file: false,
        deleted_file: false,
        renamed_file: false,
      };

      const result = DiffService.formatFileDiff(fileDiff);

      expect(result.lines[0].displayNumber).toBe(1);
      expect(result.lines[1].displayNumber).toBe(2);
    });
  });
});

import type { PR, Discussion } from '../entity/schemas';
import type { FormattedDiff, FormattedDiscussion, CommentResult } from '../service';

export interface OutputOptions {
  json: boolean;
  verbose: boolean;
}

export const Output = {
  /**
   * Output a single item
   */
  item<T>(data: T, formatter: (d: T) => string, opts: OutputOptions): void {
    if (opts.json) {
      console.log(JSON.stringify(data, null, 2));
    } else {
      console.log(formatter(data));
    }
  },

  /**
   * Output a list of items
   */
  list<T>(data: T[], formatter: (d: T) => string, opts: OutputOptions): void {
    if (opts.json) {
      console.log(JSON.stringify(data, null, 2));
    } else if (data.length === 0) {
      console.log('No items found.');
    } else {
      for (const item of data) {
        console.log(formatter(item));
      }
    }
  },

  /**
   * Output an error
   */
  error(error: Error, opts: OutputOptions): void {
    if (opts.json) {
      console.log(JSON.stringify({
        error: {
          name: error.name,
          message: error.message,
          ...(opts.verbose && { stack: error.stack }),
        },
      }, null, 2));
    } else {
      console.error(`\x1b[31mError: ${error.message}\x1b[0m`);
      if (opts.verbose && error.stack) {
        console.error(error.stack);
      }
    }
  },

  /**
   * Output success message
   */
  success(message: string): void {
    console.log(`\x1b[32m✓ ${message}\x1b[0m`);
  },

  /**
   * Format a PR for display
   */
  formatPR(pr: PR): string {
    const stateColors: Record<string, string> = {
      opened: '\x1b[32m', // green
      merged: '\x1b[35m', // magenta
      closed: '\x1b[31m', // red
      locked: '\x1b[33m', // yellow
    };
    const color = stateColors[pr.state] || '\x1b[0m';
    const reset = '\x1b[0m';

    return `${color}${pr.state}${reset} !${pr.iid} ${pr.title} (${pr.sourceBranch} → ${pr.targetBranch})`;
  },

  /**
   * Format a draft note for display
   */
  formatDraftNote(note: DraftNote): string {
    const file = note.position?.new_path ?? note.position?.old_path ?? 'general';
    const line = note.position?.new_line ?? note.position?.old_line;
    const location = line ? `${file}:${line}` : file;

    return `  ○ Draft: ${location}\n    ${note.note.split('\n').join('\n    ')}`;
  },

  /**
   * Format a session status for display
   */
  formatSessionStatus(status: {
    session: { startedAt: string; draftNoteIds: number[] } | null;
    isStale: boolean;
    draftNotes: DraftNote[];
  }): string {
    if (!status.session) {
      return 'No active review session.';
    }

    const lines: string[] = [];
    const date = new Date(status.session.startedAt).toLocaleString();

    lines.push(`Review session started: ${date}`);
    lines.push(`Draft comments: ${status.session.draftNoteIds.length}`);

    if (status.isStale) {
      lines.push('\x1b[33m⚠ Warning: MR has been updated since review started\x1b[0m');
      lines.push('Run `gfreview review refresh <id>` to update.');
    }

    if (status.draftNotes.length > 0) {
      lines.push('\nDraft notes:');
      for (const note of status.draftNotes) {
        lines.push(this.formatDraftNote(note));
      }
    }

    return lines.join('\n');
  },
};

import { Command } from 'commander';
import { GitHubClient } from '../client/github-client';
import { GitLabClient } from '../client/gitlab-client';
