import { loadConfig } from '../config';
import { Output } from './output';
import { UserError, ApiError, StaleReviewError, EXIT_CODES } from '../errors';
import type { Config } from '../entity/schemas';

interface GlobalOptions {
  forge?: 'gitlab' | 'github';
  project?: string;
  token?: string;
  baseUrl?: string;
  json: boolean;
  verbose: boolean;
}

/**
 * Parse PR ID from string (supports both numeric and #123 format)
 */
function parsePrId(id: string): number {
  if (id.startsWith('#')) {
    return parseInt(id.slice(1), 10);
  }
  return parseInt(id, 10);
}

/**
 * Create a client based on config
 */
async function createClient(config: Config) {
  if (config.forge === 'github') {
    return new GitHubClient({
      baseUrl: config.baseUrl ?? 'https://api.github.com',
      token: config.token,
    });
  } else {
    return new GitLabClient({
      baseUrl: config.baseUrl ?? 'https://gitlab.com',
      token: config.token,
    });
  }
}

/**
 * Run a command with error handling
 */
async function runCommand<T>(
  fn: () => Promise<T>,
  opts: GlobalOptions
): Promise<T> {
  try {
    return await fn();
  } catch (error) {
    if (error instanceof UserError) {
      Output.error(error, opts);
      process.exit(EXIT_CODES.USER_ERROR);
    } else if (error instanceof StaleReviewError) {
      Output.error(error, opts);
      process.exit(EXIT_CODES.STALE_REVIEW);
    } else if (error instanceof ApiError) {
      Output.error(error, opts);
      process.exit(EXIT_CODES.API_ERROR);
    } else {
      Output.error(error instanceof Error ? error : new Error(String(error)), opts);
      process.exit(EXIT_CODES.API_ERROR);
    }
  }
}

export function createProgram(): Command {
  const program = new Command();

  program
    .name('gfreview')
    .description('CLI for inline diff comments on GitLab MRs')
    .version('0.1.0')
    .option('--forge <forge>', 'Forge to use (gitlab|github)')
    .option('--project <project>', 'Project ID or path (group/repo)')
    .option('--token <token>', 'API token (or set GITLAB_TOKEN env)')
    .option('--base-url <url>', 'Base URL for self-hosted instances')
    .option('--json', 'Output as JSON')
    .option('--verbose', 'Show detailed errors and stack traces')
    .passThroughOptions();

  // List MRs
  program
    .command('list')
    .description('List merge requests')
    .option('--state <state>', 'Filter by state (opened|merged|closed|all)', 'opened')
    .option('--limit <n>', 'Maximum number to return', '100')
    .action(async (options, cmd) => {
      const globalOpts = cmd.optsWithGlobals() as GlobalOptions;

      await runCommand(async () => {
        const config = await loadConfig(globalOpts);
        const client = await createClient(config);

        const projectId = config.project;
        if (!projectId) {
          throw new UserError('No project specified. Use --project or run from a git repository.');
        }

        const prs = await client.listPRs({
          state: options.state,
          limit: parseInt(options.limit, 10),
        });

        Output.list(prs, Output.formatPR, globalOpts);
      }, globalOpts);
    });

  // View MR
  program
    .command('view <id>')
    .description('View a merge request')
    .action(async (id, options, cmd) => {
      const globalOpts = cmd.optsWithGlobals() as GlobalOptions;

      await runCommand(async () => {
        const config = await loadConfig(globalOpts);
        const client = await createClient(config);

        const projectId = config.project;
        if (!projectId) {
          throw new UserError('No project specified.');
        }

        const mrIid = parseMrId(id);
        const pr = await client.getPR(projectId, mrIid);

        Output.item(pr, Output.formatPR, globalOpts);
      }, globalOpts);
    });

  // Diff command
  program
    .command('diff <id>')
    .description('Show diff with line numbers')
    .action(async (id, options, cmd) => {
      const globalOpts = cmd.optsWithGlobals() as GlobalOptions;

      await runCommand(async () => {
        const config = await loadConfig(globalOpts);
        const client = await createClient(config);

        const projectId = config.project;
        if (!projectId) {
          throw new UserError('No project specified.');
        }

        const mrIid = parseMrId(id);
        const diffs = await DiffService.getDiff({
          client,
          projectId,
          mrIid,
        });

        if (globalOpts.json) {
