        Output.success('MR approved');
      }, globalOpts);
    });

  program
    .command('unapprove <id>')
    .description('Unapprove a merge request')
    .action(async (id, options, cmd) => {
      const globalOpts = cmd.optsWithGlobals() as GlobalOptions;

      await runCommand(async () => {
        const config = await loadConfig(globalOpts);
        const client = await createClient(config);

        const projectId = config.project;
        if (!projectId) {
          throw new UserError('No project specified.');
        }

        const mrIid = parseMrId(id);

        await client.unapprovePR(projectId, mrIid);

        Output.success('MR unapproved');
      }, globalOpts);
    });

  // Merge
  program
    .command('merge <id>')
    .description('Merge a merge request')
    .action(async (id, options, cmd) => {
      const globalOpts = cmd.optsWithGlobals() as GlobalOptions;

      await runCommand(async () => {
        const config = await loadConfig(globalOpts);
        const client = await createClient(config);

        const projectId = config.project;
        if (!projectId) {
          throw new UserError('No project specified.');
        }

        const mrIid = parseMrId(id);

        await client.mergePR(projectId, mrIid);

        Output.success('MR merged');
      }, globalOpts);
    });

  return program;
}

